export function pickNat(rng: Rng, clubId: string, league?: LeagueKind, country?: string): string {
  const table = NAT_WEIGHTS[clubId];
  if (table) return pickWeighted(rng, table, "ITA");
  if (country && COUNTRY_NATS[country]) {
    const cleaned = COUNTRY_NATS[country]!.filter(([, w]) => w > 0);
    return pickWeighted(rng, cleaned, country);
  }
  if (league === "premier" || league === "championship") return pickWeighted(rng, PREMIER_NATS, "ENG");
  if (league === "leagueOne" || league === "leagueTwo") return pickWeighted(rng, LEAGUE_ONE_NATS, "ENG");
  if (league === "serieB") return pickWeighted(rng, SERIEB_NATS, "ITA");
  if (league === "laliga" || league === "segunda" || league === "primeraFed1" || league === "primeraFed2" || league === "rfef") return pickWeighted(rng, LALIGA_NATS, "ESP");
  if (league === "bundesliga") return pickWeighted(rng, BUNDESLIGA_NATS, "GER");
  if (league === "bundesliga2") return pickWeighted(rng, BUNDESLIGA2_NATS, "GER");
  if (league === "bundesliga3") return pickWeighted(rng, BUNDESLIGA3_NATS, "GER");
  if (league === "ligue1") return pickWeighted(rng, LIGUE1_NATS, "FRA");
  if (league === "ligue2" || league === "ligue3") return pickWeighted(rng, LIGUE2_NATS, "FRA");
  if (
    league === "argentina" ||
    league === "primeraNacional" ||
    league === "primeraBMetro" ||
    league === "argentinaCuarta" ||
    league === "argentinaQuinta" ||
    league === "promocionalAmateur"
  ) return pickWeighted(rng, COUNTRY_NATS.ARG!, "ARG");
  if (league === "conmebol" || league === "brasileirao" || league === "brasileiraoB" || league === "brasileiraoC") return pickWeighted(rng, COUNTRY_NATS.BRA!, "BRA");
  if (league === "europe" || league === "primeira" || league === "primeira2") return pickWeighted(rng, COUNTRY_NATS.POR!, "POR");
  if (league === "eredivisie" || league === "eersteDivisie" || league === "tweedeDivisie") return pickWeighted(rng, COUNTRY_NATS.NED!, "NED");
  if (league === "mls" || league === "uslChampionship") return pickWeighted(rng, COUNTRY_NATS.USA!, "USA");
  if (league === "saudiProLeague" || league === "saudiFirstDivision") return pickWeighted(rng, COUNTRY_NATS.KSA!, "KSA");
  if (league === "afc") return pickWeighted(rng, COUNTRY_NATS.KSA!, "BRA");
  if (league === "caf") return pickWeighted(rng, COUNTRY_NATS.EGY!, "NGA");
  if (league === "concacaf") return pickWeighted(rng, COUNTRY_NATS.MEX!, "MEX");
  if (league === "ofc") return pickWeighted(rng, COUNTRY_NATS.NZL!, "ENG");
  return pickWeighted(rng, NAT_WEIGHTS.default!, "ITA");
}

