export function makeName(rng: Rng, nat: string, used: Set<string>): string {
  const pool = FIRST[nat] ? nat : (NAME_POOL_FALLBACK[nat] ?? "ITA");
  const candidates = availableNameCandidates(pool, used);

  while (candidates.candidates.length > 0) {
    const index = rng.int(0, candidates.candidates.length - 1);
    const name = candidates.candidates[index]!;
    const last = candidates.candidates.pop()!;
    if (index < candidates.candidates.length) candidates.candidates[index] = last;
    if (used.has(name)) continue;
    rememberUsedName(used, name);
    return name;
  }

  return fallbackName(rng, pool, used, candidates);
}

function fallbackName(
  rng: Rng,
  pool: string,
  used: Set<string>,
  candidates: NamePoolAvailability,
): string {
  const firsts = FIRST[pool] ?? FIRST.ITA!;
  const lasts = LAST[pool] ?? LAST.ITA!;
  const pairCount = firsts.length * lasts.length;
  const fallbackCount = pairCount * INITIALS.length;
  for (let offset = 0; offset < fallbackCount; offset++) {
    const index = (candidates.fallbackIndex + offset) % fallbackCount;
    const pair = Math.floor(index / INITIALS.length);
    const first = firsts[Math.floor(pair / lasts.length)]!;
    const last = lasts[pair % lasts.length]!;
    const initial = index % INITIALS.length;
    const name = `${first} ${INITIALS[initial]}. ${last}`;
    if (!used.has(name)) {
      candidates.fallbackIndex = (index + 1) % fallbackCount;
      rememberUsedName(used, name);
      return name;
    }
  }

  for (let i = 0; i < 64; i++) {
    const n = `${rng.pick(firsts)} ${rng.pick(lasts)}-${rng.pick(lasts)}`;
    if (!used.has(n)) {
      rememberUsedName(used, n);
      return n;
    }
  }
  const first = rng.pick(firsts);
  const last = rng.pick(lasts);
  const n = `${first} ${last} Jr.`;
  rememberUsedName(used, n);
  return n;
}

const INITIALS = "ABCDEFGHIJKLMNOPRSTVZ".split("");
const NAME_CANDIDATE_CACHE = new Map<string, string[]>();
type NamePoolAvailability = { candidates: string[]; fallbackIndex: number };
const NAME_AVAILABILITY = new WeakMap<Set<string>, Map<string, NamePoolAvailability>>();
const NORMALIZED_USED_NAMES = new WeakMap<Set<string>, Set<string>>();

function normalizedName(name: string) {
  return name.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLocaleLowerCase();
}

export function normalizedUsedNames(used: Set<string>): Set<string> {
  let normalized = NORMALIZED_USED_NAMES.get(used);
  if (!normalized) {
    normalized = new Set([...used].map(normalizedName));
    NORMALIZED_USED_NAMES.set(used, normalized);
  }
  return normalized;
}

export function rememberUsedName(used: Set<string>, name: string) {
  used.add(name);
  NORMALIZED_USED_NAMES.get(used)?.add(normalizedName(name));
}

function availableNameCandidates(pool: string, used: Set<string>): NamePoolAvailability {
  let byPool = NAME_AVAILABILITY.get(used);
  if (!byPool) {
    byPool = new Map();
    NAME_AVAILABILITY.set(used, byPool);
  }

  let available = byPool.get(pool);
  if (!available) {
    available = { candidates: [...cachedNameCandidates(pool)], fallbackIndex: 0 };
    byPool.set(pool, available);
  }
  return available;
}

function cachedNameCandidates(nat: string): string[] {
  const pool = FIRST[nat] ? nat : (NAME_POOL_FALLBACK[nat] ?? "ITA");
  const cached = NAME_CANDIDATE_CACHE.get(pool);
  if (cached) return cached;

  const firsts = FIRST[pool] ?? FIRST.ITA!;
  const lasts = LAST[pool] ?? LAST.ITA!;
  const generated: string[] = [];
  for (const first of firsts) {
    for (const last of lasts) {
      generated.push(`${first} ${last}`);
    }
  }
  NAME_CANDIDATE_CACHE.set(pool, generated);
  return generated;
}

/** Nombre terminado en número (p. ej. "Marco Rossi 7"), como los generaba la versión anterior. */
export function hasNameNumber(name: string): boolean {
  return /\s+\d+$/.test(name);
}

/** Nombre genérico de relleno ("Jugador 1", "JUGADOR 2"): nunca debe llegar a una plantilla. */
export function isGenericPlayerName(name: string): boolean {
  return /^jugador\s*\d*$/i.test(name.trim());
}

/** Quita el número final del nombre; si el resultado ya existe, agrega una inicial para no duplicar. */
export function cleanNameNumber(name: string, used: Set<string>): string {
  const base = name.replace(/\s+\d+$/, "").trim();
  if (!used.has(base)) return base;
  const parts = base.split(/\s+/);
  const first = parts[0] ?? base;
  const rest = parts.slice(1).join(" ");
  for (const letter of INITIALS) {
    const n = rest ? `${first} ${letter}. ${rest}` : `${first} ${letter}.`;
    if (!used.has(n)) return n;
  }
  return `${base} Jr.`;
}

export type StarSeed = {
  name: string;
  pos: Pos;
  ovr: number;
  age: number;
  nat: string;
  pot?: number;
  sourceId?: string;
  /** Published transfer-market reference; distinct from the game's calculated player value and wage. */
  marketValueEur?: number | null;
  /** Published contract expiry when available; contract is the in-game remaining-term estimate. */
  contractExpiry?: string | null;
  contract?: number;
  loanFrom?: string;
};

/** Agentes libres con nombre propio: se suman a los generados al azar al empezar una partida. */
export interface FreeAgentSeed {
  name: string;
  pos: Pos;
  ovr: number;
  pot: number;
  age: number;
  nat: string;
}

